import { GL_R8, GL_RED, GL_UNSIGNED_BYTE } from "../../core/constants";
import type { DataTextureParams } from "../../core/texture";

// 32x32 void-and-cluster blue-noise threshold mask, one byte per pixel,
// each byte being floor(rank * 256 / 1024). Generated by
// scripts/gen-blue-noise.mjs (sigma 1.5), do not edit by hand.
const encoded =
  "";

let _mask: DataTextureParams | undefined;

/**
 * Returns the shared blue-noise threshold mask as a texture description.
 * Decoded on first use so nothing runs at module load time.
 * @internal
 */
export function blueNoiseMask(): DataTextureParams {
  if (_mask) return _mask;

  const data = Uint8Array.from(atob(encoded), (c) => c.charCodeAt(0));

  _mask = {
    data,
    width: 32,
    height: 32,
    format: GL_RED,
    internalFormat: GL_R8,
    type: GL_UNSIGNED_BYTE,
    minFilter: "nearest",
    magFilter: "nearest",
    wrapS: "repeat",
    wrapT: "repeat",
    flipY: false,
  };

  return _mask;
}
